import{state,dispose}from"../store";import{getExitUrl}from"../getters";describe("upsell getExitUrl",(()=>{beforeEach((()=>{dispose(),state.form_id="instant-checkout",window.location="https://shop.test/upsell"})),it("follows a same-origin metadata.success_url",(()=>{state.success_url="/seeded",state.checkout={id:"co_1",metadata:{success_url:"https://shop.test/meta"}},expect(getExitUrl()).toBe("https://shop.test/meta")})),it("falls back to the seeded success_url for an off-site metadata value",(()=>{state.success_url="/seeded",state.checkout={id:"co_1",metadata:{success_url:"https://evil.example/phish"}},expect(getExitUrl()).toBe("/seeded")})),it("is null when the metadata value is off-site and nothing is seeded",(()=>{state.success_url=null,state.checkout={id:"co_1",metadata:{success_url:"//evil.example/phish"}},expect(getExitUrl()).toBeNull()})),it("leaves an off-site seeded success_url alone",(()=>{state.success_url="https://courses.example/welcome",state.checkout={id:"co_1"},expect(getExitUrl()).toBe("https://courses.example/welcome")})),it("follows any metadata.success_url outside instant checkout, as before",(()=>{state.form_id=0,state.success_url="/seeded",state.checkout={id:"co_1",metadata:{success_url:"https://elsewhere.example/thanks"}},expect(getExitUrl()).toBe("https://elsewhere.example/thanks")}))}));